package org.sleepwell.app;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.*;
import android.provider.Settings;
import java.util.*;

/** Private relative nap scheduling. All transitions share the alarm occurrence lock. */
final class Naps {
 static final String DEADLINE="org.sleepwell.app.NAP_DEADLINE";
 interface Ports {NapEngine.Port create(Context c);}
 static Ports ports=Platform::new;
 static java.util.function.Function<Context,NapPlan.Clock> clocks=Naps::platformClock;
 static java.util.function.BooleanSupplier activeTracking=()->{TrackingService.Snapshot s=TrackingService.snapshot();return s!=null&&s.phase.equals("ACTIVE")&&s.motion;};
 private static NapPlan.Clock platformClock(Context c){String key="napDeviceId";String existing=Prefs.text(c,key,"");if(existing.isEmpty()){existing=UUID.randomUUID().toString();if(!Prefs.of(c).edit().putString(key,existing).commit())throw new IllegalStateException("Could not save timer identity.");}String device=existing;return new NapPlan.Clock(){public long wall(){return System.currentTimeMillis();}public long elapsed(){return SystemClock.elapsedRealtime();}public long boot(){return Settings.Global.getInt(c.getContentResolver(),Settings.Global.BOOT_COUNT,0);}public String device(){return device;}};}
 static NapPlan.Clock clock(Context c){return clocks.apply(c.getApplicationContext());}
 static NapEngine engine(Context c){Context app=c.getApplicationContext();Records.Factory pinned=Records.factory;return new NapEngine(new NapEngine.Repository(){public NapEngine.Entry load(int id){try(Store store=pinned.open(app)){Alarm a=store.alarm(id);return a==null?null:new NapEngine.Entry(a.nap,a.enabled);}}public void save(int id,NapPlan p,boolean enabled){try(Store store=pinned.open(app)){Alarm a=store.alarm(id);if(a==null||a.nap==null||!a.nap.nonce.equals(p.nonce))throw new IllegalStateException("This nap has changed. Reopen it.");a.nap=p;a.enabled=enabled;store.save(a);Alarm saved=store.alarm(id);if(saved==null||!saved.json().toString().equals(a.json().toString()))throw new IllegalStateException("Nap could not be saved.");}}},ports.create(app),clock(app));}
 static Alarm start(Context c,Alarm draft,int minutes,long startAt,boolean delete){synchronized(Scheduler.class){if(Prefs.flag(c,"ringing"))throw new IllegalStateException("Finish the current alarm before starting a nap.");String access=ports.create(c).access();if(!access.isEmpty())throw new SecurityException(access);if(draft.smartWindow>0&&!activeTracking.getAsBoolean())throw new IllegalStateException("Start phone movement tracking first, or turn Smart wake-up off.");NapPlan.Clock clock=clock(c);long delay=startAt==0?0:Math.subtractExact(startAt,clock.wall());NapPlan plan=NapPlan.create(clock,minutes,delay,delete);try(Store store=Records.open(c)){Alarm old=draft.id>0?store.alarm(draft.id):null;if(draft.id>0&&(old==null||old.nap==null||draft.nap==null||!old.nap.nonce.equals(draft.nap.nonce)))throw new IllegalStateException("This nap has changed. Reopen it.");if(old!=null&&old.enabled&&old.nap.phase==NapPlan.Phase.PENDING)throw new IllegalStateException("This nap is already running. Cancel it before starting another timer.");if(old!=null&&old.nap.phase==NapPlan.Phase.CLAIMED)throw new IllegalStateException("Complete the active nap alarm first.");Alarm a=Alarm.read(draft.json());if(a.id<=0){a.id=store.alarms().stream().mapToInt(row->row.id).max().orElse(0)+1;if(a.id<=0)throw new IllegalStateException("No alarm slots are available.");}a.days.clear();a.label=minutes+" minute nap";a.nap=plan;a.napInvalid=false;a.enabled=true;a.smartWindow=a.smartWindow>0?Math.min(5,minutes):0;java.time.ZonedDateTime end=java.time.Instant.ofEpochMilli(plan.deadlineWall()).atZone(java.time.ZoneId.systemDefault());a.hour=end.getHour();a.minute=end.getMinute();store.save(a);Alarm saved=store.alarm(a.id);if(saved==null||saved.nap==null||!saved.nap.nonce.equals(plan.nonce))throw new IllegalStateException("Nap could not be saved.");if(old!=null){try{ports.create(c).cancel(old.id,old.nap);}catch(RuntimeException ignored){/* Replacement nonce fences the old broadcast. */}cancelCheck(c,old);}engine(c).reconcile(a.id);return store.alarm(a.id);}}}
 static void cancelCheck(Context c,Alarm old){WakeCheckState check=WakeChecks.snapshot(c);if(check==null||check.alarmId!=old.id||old.nap==null)return;try{Alarm source=Alarm.read(new org.json.JSONObject(check.alarm));if(source.nap!=null&&source.nap.nonce.equals(old.nap.nonce))WakeChecks.cancelForAlarm(c,old.id);}catch(org.json.JSONException invalid){/* An unowned corrupt check must not be cancelled by an unrelated timer. */}}
 static void reconcile(Context c,int id){synchronized(Scheduler.class){engine(c).reconcile(id);}}
 static void receive(Context c,int id,String nonce){synchronized(Scheduler.class){engine(c).receive(id,nonce,false);}}
 static boolean movement(Context c,Alarm alarm,double normalized,int active,int samples){synchronized(Scheduler.class){if(alarm.nap==null||!alarm.enabled||!alarm.nap.smartReady(clock(c),alarm.smartWindow,normalized,active,samples))return false;engine(c).receive(alarm.id,alarm.nap.nonce,true);try(Store store=Records.open(c)){Alarm saved=store.alarm(alarm.id);return saved!=null&&saved.nap!=null&&saved.nap.nonce.equals(alarm.nap.nonce)&&saved.nap.phase==NapPlan.Phase.CLAIMED;}}}
 static void cancel(Context c,Alarm a){if(a.nap==null)return;synchronized(Scheduler.class){engine(c).cancel(a.id,a.nap.nonce);}}
 static void cancelJob(Context c,Alarm a){if(a.nap!=null)ports.create(c).cancel(a.id,a.nap);}
 static void dismissed(Context c,Alarm active,boolean checkPending){if(active.nap==null)return;synchronized(Scheduler.class){try(Store store=Records.open(c)){Alarm saved=store.alarm(active.id);if(saved==null||saved.nap==null||!saved.nap.nonce.equals(active.nap.nonce)||saved.nap.phase!=NapPlan.Phase.CLAIMED)return;if(saved.nap.deleteAfter&&!checkPending)store.deleteAlarm(saved.id);else{saved.nap=saved.nap.state(NapPlan.Phase.FINISHED,"");saved.enabled=false;store.save(saved);}}}}
 static void confirmed(Context c,WakeCheckState check){try{Alarm active=Alarm.read(new org.json.JSONObject(check.alarm));if(active.nap==null)return;try(Store store=Records.open(c)){Alarm saved=store.alarm(active.id);if(saved!=null&&saved.nap!=null&&saved.nap.deleteAfter&&saved.nap.nonce.equals(active.nap.nonce)&&(saved.nap.phase==NapPlan.Phase.FINISHED||saved.nap.phase==NapPlan.Phase.CLAIMED))store.deleteAlarm(saved.id);}}catch(org.json.JSONException invalid){throw new IllegalStateException(invalid);}}
 static void restored(Alarm a){if(a.nap!=null)a.nap=a.nap.state(NapPlan.Phase.CANCELLED,"");}
 private static final class Platform implements NapEngine.Port {
  final Context c;Platform(Context c){this.c=c;}
  public String access(){if(!Scheduler.allowed(c))return "Allow Alarms & reminders before starting a nap.";NotificationManager n=c.getSystemService(NotificationManager.class);if(!n.areNotificationsEnabled()||Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return "Allow alarm notifications before starting a nap.";NotificationChannel channel=n.getNotificationChannel(Notifications.ALARM);if(channel!=null&&channel.getImportance()<NotificationManager.IMPORTANCE_HIGH)return "Allow high-importance Wake-up alarm notifications before starting a nap.";if(Build.VERSION.SDK_INT>=34&&!n.canUseFullScreenIntent())return "Allow full-screen alarms before starting a nap.";return "";}
  private PendingIntent pending(int id,NapPlan p,int flags){return PendingIntent.getBroadcast(c,id,new Intent(c,NapReceiver.class).setAction(DEADLINE).setIdentifier("nap:"+id+":"+p.nonce).putExtra("id",id).putExtra("nonce",p.nonce),flags|PendingIntent.FLAG_IMMUTABLE);}
  public void schedule(int id,NapPlan p,long delay){if(!access().isEmpty())throw new SecurityException(access());PendingIntent review=PendingIntent.getActivity(c,id,new Intent(c,NapActivity.class).putExtra("id",id).setIdentifier("nap-review:"+id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);c.getSystemService(AlarmManager.class).setAlarmClock(new AlarmManager.AlarmClockInfo(Math.addExact(System.currentTimeMillis(),delay),review),pending(id,p,PendingIntent.FLAG_UPDATE_CURRENT));}
  public void cancel(int id,NapPlan p){PendingIntent operation=pending(id,p,PendingIntent.FLAG_NO_CREATE);if(operation!=null){c.getSystemService(AlarmManager.class).cancel(operation);operation.cancel();}}
  public void fire(int id,NapPlan p){if(Prefs.flag(c,"ringing"))throw new IllegalStateException("Another alarm is active.");try(Store store=Records.open(c)){Alarm a=store.alarm(id);if(a==null||a.nap==null||!a.nap.nonce.equals(p.nonce)||a.nap.phase!=NapPlan.Phase.CLAIMED)throw new IllegalStateException("Nap ownership changed.");SleepSoundService.alarmStarting();Prefs.put(c,"snoozes_"+id,0);Scheduler.fire(c,a,false);}}
 }
 private Naps(){}
}
